      "clickhouse_external_parquet_scan_max_threads": {
        "label": "Threads für Scans",
        "help": "Mindestzahl an Threads für Aggregationen, Pivots, Sortierungen und Joins auf Dateien im Speicher: Lesen aus S3 wartet auf das Netzwerk, und mehr Threads verbergen das Warten. Lässt die Tabellenansicht unberührt und geht nie unter die Kerne des Servers. 0 = ClickHouse entscheidet.",
      },
      "clickhouse_external_max_execution_time": {
        "label": "Höchstdauer einer Abfrage",
        "help": "Nach dieser Zeit bricht ClickHouse die Abfrage ab. Gilt ab dem nächsten Lauf. 0 = keine Grenze (Vorschauen haben ohnehin ihre eigene).",
      },
      "clickhouse_external_materialize_min_rows": {
        "label": "Kopie für den Viewer ab (Zeilen)",
        "help": "Ab dieser Zeilenzahl wird ein im Viewer geöffneter Datensatz einmal in eine ClickHouse-Tabelle kopiert, und die folgenden Scans sind 2- bis 6-mal schneller. Die Kopie entsteht bei der ersten Anfrage, die dadurch deutlich langsamer werden kann. 0 = aus.",
      },
      "clickhouse_external_materialize_ttl_seconds": {
        "label": "Haltbarkeit der Viewer-Kopien",
        "help": "Wie lange eine Kopie ungenutzt bleiben darf, bevor sie vom ClickHouse-Server entfernt wird.",
      },
      "bigquery_maximum_bytes_billed": {
        "label": "Höchstzahl abgerechneter Bytes pro Abfrage",
        "help": "BigQuery lehnt eine Abfrage, die mehr lesen würde, schon vor der Ausführung ab: Das schützt die Rechnung. 0 = keine Grenze.",
      },
